import {formatDebtAmount,validDebtAmount} from './debt-currency.mjs';
import { t } from './i18n.mjs';
export const cardEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=cardEscape;
function safePhoto(url){return typeof url==='string'&&(/^(https?:\/\/|\/|assets\/)/.test(url)||/^data:image\/(png|jpeg|webp);base64,/.test(url))?url:null;}
export function debtCardHTML(card,{saved=false,sample=false,id=''}={}){const photo=safePhoto(card.photo);return `<article class="debt-face"><div class="debt-face-art ${photo?'has-photo':''}">${photo?`<img src="${e(photo)}" alt="${t(`Profile picture of ${e(card.name)}`,`Ảnh đại diện của ${e(card.name)}`,`${e(card.name)}님의 프로필 사진`)}">`:'<div class="df-sun"></div><div class="df-hill"></div><div class="df-hill second"></div><div class="df-heart">♡</div>'}${sample?'<span class="df-sample">'+t("Sample profile","Hồ sơ mẫu","예시 프로필")+'</span>':''}</div><div class="df-body"><div class="df-person"><h2>${e(card.name)}${card.age?`<span>, ${e(card.age)}</span>`:''}</h2>${card.location?`<p>⌖ ${e(card.location)}</p>`:''}</div><div class="df-titles">${card.debts.map((d,index)=>`<div><span>${String(index+1).padStart(2,'0')}</span><h3>${e(d.title)}</h3>${validDebtAmount(d.amount,d.currency)?`<strong class="df-amount">${formatDebtAmount(d.amount,d.currency)}</strong>`:''}</div>`).join('')}</div><div class="df-bottom"><p>${t("Tap the app logo to learn more about this card.","Nhấn logo ứng dụng để xem thêm về thẻ này.","앱 로고를 눌러 카드의 자세한 내용을 확인하세요.")}</p><div class="df-actions"><button class="df-skip" data-dc="skip" data-id="${e(id)}" aria-label="${t("Skip card","Bỏ qua thẻ","카드 건너뛰기")}"><b>×</b><span>${t("Skip","Bỏ qua","건너뛰기")}</span></button><button class="df-save ${saved?'is-saved':''}" data-dc="save" data-id="${e(id)}" aria-label="${saved?t("Unsave card","Bỏ lưu thẻ","카드 저장 취소"):t("Save card","Lưu thẻ","카드 저장")}" aria-pressed="${saved}"><b>${saved?'★':'☆'}</b><span>${saved?t("Saved","Đã lưu","저장됨"):t("Save","Lưu","저장")}</span></button><button class="df-learn" data-dc="detail" data-id="${e(id)}" aria-label="${t("View card details","Xem thêm thông tin chi tiết","카드 상세 보기")}"><span class="df-logo-icon"><img src="assets/debtfreelately-mark-clean.png" alt="${t("DebtFreeLately logo","Logo DebtFreeLately","DebtFreeLately 로고")}"></span><span>${t("Details","Chi tiết","상세 보기")}</span></button></div></div></div></article>`;}
export function cardDetailsHTML(card){return `<div class="eyebrow">${t("DEBT CARD · PUBLIC DETAILS","DEBT CARD · THÔNG TIN HIỂN THỊ","채무 카드 · 공개 정보")}</div><h2>${e(card.name)}${card.age?t(`, ${e(card.age)} years old`,`, ${e(card.age)} tuổi`,`, ${e(card.age)}세`):''}</h2>${card.location?`<p>⌖ ${e(card.location)}</p>`:''}${card.debts.map(d=>`<h3>${e(d.title)}</h3>${validDebtAmount(d.amount,d.currency)?`<p><strong>${formatDebtAmount(d.amount,d.currency)}</strong></p>`:''}<p class="detail-story">${d.story?e(d.story):t("The card owner has kept this debt story private.","Người đăng đang giữ riêng tư câu chuyện của khoản nợ này.","카드 작성자가 이 채무 이야기를 비공개로 설정했습니다.")}</p>`).join('')}`;}
